4	import 'package:flutter/material.dart';
5	
6	abstract final class Json {
7	  static String str(Map<String, dynamic> j, String k, [String fallback = '']) =>
8	      j[k] as String? ?? fallback;
9	
10	  static String? optStr(Map<String, dynamic> j, String k) => j[k] as String?;
11	
12	  static int intg(Map<String, dynamic> j, String k, [int fallback = 0]) {
13	    final v = j[k];
14	    if (v is int) return v;
15	    if (v is num) return v.toInt();
16	    return int.tryParse('$v') ?? fallback;
17	  }
18	
19	  static double? optDouble(Map<String, dynamic> j, String k) {
20	    final v = j[k];
21	    if (v is num) return v.toDouble();
22	    return double.tryParse('$v');
23	  }
24	
25	  static bool flag(Map<String, dynamic> j, String k, [bool fallback = false]) =>
26	      j[k] as bool? ?? fallback;
27	
28	  static List<String> strings(Map<String, dynamic> j, String k) =>
29	      (j[k] as List<dynamic>? ?? const []).map((e) => '$e').toList(growable: false);
30	
31	  static DateTime? date(Map<String, dynamic> j, String k) =>
32	      DateTime.tryParse('${j[k]}')?.toLocal();
33	
34	  static T child<T>(Map<String, dynamic> j, String k, T Function(Map<String, dynamic>) fromJson) =>
35	      fromJson(j[k] as Map<String, dynamic>? ?? const {});
